func:
// Loads the Provideam proof settings and the shared Insights Hub Config.
// In: manual trigger. Out: one report request body with the day set,
// the lake base address and the lake folder.
var PROVIDEAM_API_KEY = 'PASTE_PROVIDEAM_API_KEY_HERE';
// Paste one saved body from docs/provideam-samples/<nn>-*.md (JSON text).
var REPORT_BODY_JSON = 'PASTE_REPORT_BODY_JSON_HERE';
var REPORT_NAME = 'new-plan-opt-report';
// Production day YYYY-MM-DD. Empty = yesterday (UTC date).
var DAY = '';
var LAKE_FOLDER = 'mufti_test/provideam';
var PROVIDEAM_URL = 'https://rb-api.provideam.com';
PROVIDEAM_URL += '/api/v1/Report/ObjectByPeriod';
var cfg = glob.get('cfg');

if (!cfg || cfg.platform !== 'xcelerator' || !cfg.xcTenantId) {
  msg.proofFailureReason = 'Run Config with xcelerator selected first';
  node.error(msg.proofFailureReason, msg);
  return null;
}
if (PROVIDEAM_API_KEY.indexOf('PASTE_') === 0 ||
  REPORT_BODY_JSON.indexOf('PASTE_') === 0) {
  msg.proofFailureReason = 'Fill in the Provideam proof settings';
  node.error(msg.proofFailureReason, msg);
  return null;
}

var body;
try {
  body = JSON.parse(REPORT_BODY_JSON);
} catch (e) {
  msg.proofFailureReason = 'REPORT_BODY_JSON is not valid JSON';
  node.error(msg.proofFailureReason, msg);
  return null;
}

var day = DAY;
if (!day) {
  var d = new Date(Date.now() - 86400000);
  day = d.toISOString().slice(0, 10);
}
if (!/^\d{4}-\d\d-\d\d$/.test(day)) {
  msg.proofFailureReason = 'DAY must be YYYY-MM-DD';
  node.error(msg.proofFailureReason, msg);
  return null;
}
// Provideam period text: one day as [<day>T00:00:00].
body.periods = [
  {
    periodParam: {
      pdDay: ['[' + day + 'T00:00:00]']
    }
  }
];

msg.proof = {
  apiKey: PROVIDEAM_API_KEY,
  url: PROVIDEAM_URL,
  body: body,
  day: day,
  lakeFolder: LAKE_FOLDER
};
msg.proofFile = {
  name: REPORT_NAME + '_' + day + '.json'
};
msg.lakeBase = 'https://api.eu1.siemens.app/datalake-';
msg.lakeBase += cfg.xcTenantId + '/v3';
msg._proofStage = 'settings';
node.status({ fill: 'green', shape: 'dot', text: 'settings ready' });
return msg;

// Builds the Provideam report request (read-style POST).
// In: proof settings. Out: an HTTP request for one report day.
// Provideam answers HTTP 500 to a body with more than 18 functions.
msg.method = 'POST';
msg.url = msg.proof.url;
msg.headers = {
  'apiKey': msg.proof.apiKey,
  'Content-Type': 'application/json-patch+json',
  'Accept': 'application/json'
};
msg.payload = JSON.stringify(msg.proof.body);
msg._proofStage = 'Provideam report';
node.status({ fill: 'blue', shape: 'dot', text: 'calling Provideam' });
return msg;

// Checks the Provideam response and keeps its text as it came.
// In: report response as text. Out: the bytes to store and the row count.
if (msg.statusCode !== 200) {
  msg.proofFailureReason = 'Provideam HTTP ' + msg.statusCode;
  node.error(msg.proofFailureReason, msg);
  return null;
}

var text = String(msg.payload || '');
var rows;
try {
  rows = JSON.parse(text).processedData;
} catch (e) {
  msg.proofFailureReason = 'Provideam response is not JSON';
  node.error(msg.proofFailureReason, msg);
  return null;
}
if (!Array.isArray(rows)) {
  msg.proofFailureReason = 'Provideam response has no processedData';
  node.error(msg.proofFailureReason, msg);
  return null;
}

msg.fileBytes = Buffer.from(text, 'utf8');
msg.fileSize = msg.fileBytes.length;
msg.rowCount = rows.length;
delete msg.proof.apiKey;
delete msg.headers;
delete msg.payload;
node.status({
  fill: 'blue',
  shape: 'dot',
  text: rows.length + ' rows from Provideam'
});
return msg;

// Builds the Insights Hub client-credentials request.
// In: proof settings. Out: an HTTP request for the lake token.
var cfg = glob.get('cfg');

if (!cfg || !cfg.clientId || !cfg.clientSecret || !cfg.tokenUrl) {
  msg.proofFailureReason = 'Insights Hub credentials are missing in Config';
  node.error(msg.proofFailureReason, msg);
  return null;
}

msg.method = 'POST';
msg.url = cfg.tokenUrl;
msg.headers = {
  'Authorization': 'Basic ' + Buffer.from(
    cfg.clientId + ':' + cfg.clientSecret
  ).toString('base64'),
  'Accept': 'application/json'
};
if (cfg.tokenForm) {
  msg.headers['Content-Type'] = 'application/x-www-form-urlencoded';
  msg.payload = 'grant_type=client_credentials';
} else {
  delete msg.payload;
}
msg._proofStage = 'Insights Hub token';
node.status({ fill: 'blue', shape: 'dot', text: 'requesting lake token' });
return msg;

// Checks and retains the Insights Hub token for the proof.
// In: token HTTP response. Out: the same message with msg.lakeToken.
var token = msg.payload && msg.payload.access_token;

if (msg.statusCode !== 200 || !token) {
  msg.proofFailureReason = 'Insights Hub token HTTP ' + msg.statusCode;
  node.error(msg.proofFailureReason, msg);
  return null;
}

msg.lakeToken = token;
delete msg.payload;
msg._proofStage = 'lake token';
node.status({ fill: 'blue', shape: 'dot', text: 'lake token ready' });
return msg;

// Requests a lake upload URL for the stored report text.
// In: lake token and file bytes. Out: an authenticated lake URL request.
var folder = String(msg.proof.lakeFolder || '');
folder = folder.replace(/^\/+|\/+$/g, '');
var name = msg.proofFile.name;
var validPath = /^[A-Za-z0-9 .!*'()_/-]+$/;

if (!folder || folder.indexOf('..') !== -1 ||
  folder.indexOf('data/ten=') === 0 || !validPath.test(folder) ||
  !/^[A-Za-z0-9 .!*'()_-]+$/.test(name)) {
  msg.proofFailureReason = 'Invalid lake path or file name';
  node.error(msg.proofFailureReason, msg);
  return null;
}

msg.lakePath = folder + '/' + name;
msg.method = 'POST';
msg.url = msg.lakeBase + '/generateUploadObjectUrls';
msg.headers = {
  'Authorization': 'Bearer ' + msg.lakeToken,
  'Content-Type': 'application/json',
  'Accept': 'application/json'
};
msg.payload = {
  paths: [
    { path: msg.lakePath }
  ]
};
msg._proofStage = 'lake signed URL';
node.status({
  fill: 'blue',
  shape: 'dot',
  text: 'requesting lake upload URL'
});
return msg;

// Builds the unauthenticated PUT request for the signed lake URL.
// In: signed-URL response and file bytes. Out: a binary HTTP PUT request.
var body = msg.payload;
var signedUrl = body && body.objectUrls &&
  body.objectUrls[0] && body.objectUrls[0].signedUrl;
var bytes = msg.fileBytes;

if (bytes && bytes.type === 'Buffer' && Array.isArray(bytes.data)) {
  bytes = Buffer.from(bytes.data);
}

if (msg.statusCode !== 201 || !signedUrl) {
  msg.proofFailureReason = 'Lake signed URL HTTP ' + msg.statusCode;
  node.error(msg.proofFailureReason, msg);
  return null;
}
if (!Buffer.isBuffer(bytes)) {
  msg.proofFailureReason = 'Downloaded bytes are not a binary Buffer';
  node.error(msg.proofFailureReason, msg);
  return null;
}

msg.signedUrl = signedUrl;
msg.method = 'PUT';
msg.url = signedUrl;
msg.headers = {};
msg.payload = bytes;
delete msg.fileBytes;
msg._proofStage = 'lake file upload';
node.status({ fill: 'blue', shape: 'dot', text: 'uploading one file' });
return msg;

// Reports the stored file without exposing keys, tokens or signed URLs.
// In: signed PUT response. Out: a short debug message.
if (msg.statusCode !== 200) {
  msg.proofFailureReason = 'Lake PUT HTTP ' + msg.statusCode;
  node.error(msg.proofFailureReason, msg);
  return null;
}

var text = 'UPLOADED ' + msg.proofFile.name;
text += ' (' + msg.rowCount + ' rows, ' + msg.fileSize + ' bytes) to ';
text += msg.lakePath;
msg.payload = text;
delete msg.proof;
delete msg.lakeToken;
delete msg.signedUrl;
delete msg.url;
delete msg.headers;
delete msg.method;
delete msg.fileBytes;
delete msg._proofStage;
node.status({ fill: 'green', shape: 'dot', text: 'lake upload complete' });
return msg;

// Reports a sanitized proof failure.
// In: a caught error. Out: a short debug message without request details.
var stage = msg._proofStage || 'proof';
var reason = msg.proofFailureReason || 'request failed';
var name = msg.proofFile && msg.proofFile.name;
var text = 'FAILED ' + stage;

if (name) {
  text += ' ' + name;
}
text += ': ' + reason;
msg.payload = text;
delete msg.proof;
delete msg.lakeToken;
delete msg.signedUrl;
delete msg.url;
delete msg.headers;
delete msg.method;
delete msg.fileBytes;
delete msg._proofStage;
delete msg.proofFailureReason;
node.status({ fill: 'red', shape: 'ring', text: 'proof failed' });
return msg;
